#include <iostream>

// Returns a dynamically allocated reversed array
int* reverseArray(const int* list, int size) {
    int* result = new int[size];
    for (int i = 0, j = size - 1; i < size; ++i, --j) {
        result[j] = list[i];
    }
    return result;
}

void printArray(const int* list, int size) {
    for (int i = 0; i < size; ++i) {
        std::cout << list[i] << (i + 1 < size ? " " : "");
    }
    std::cout << "\n";
}

int main() {
    const int original[] = {1, 2, 3, 4, 5, 6};
    int size = 6;

    // Allocate on heap inside function and receive pointer
    int* reversed = reverseArray(original, size);

    printArray(reversed, size);

    // Clean up heap memory properly using array delete
    delete[] reversed;
    reversed = nullptr; // Eliminate dangling pointer

    return 0;
}

