#include <iostream>
#include <string>

class Student {
private:
    std::string name;
    int score;
public:
    Student() : name("Anonymous"), score(0) {}
    Student(const std::string& n, int s) : name(n), score(s) {}

    std::string getName() const { return name; }
    int getScore() const { return score; }
    void addBonus(int bonus) { score += bonus; }
};

int main() {
    // 1. Dynamic object with no-arg constructor
    Student* s1 = new Student;
    std::cout << (*s1).getName() << ": " << (*s1).getScore() << "\n";

    // 2. Dynamic object with arguments and arrow operator
    Student* s2 = new Student("Alice", 95);
    s2->addBonus(3);
    std::cout << s2->getName() << ": " << s2->getScore() << "\n";

    // 3. Clean up
    delete s1;
    delete s2;
    s1 = nullptr;
    s2 = nullptr;

    return 0;
}
